# Hypothesis from test grid: there is one clean repeated shape; noise pixels are stragglers.
# In demo: what does each color's full set look like as union of copies? 
# Try: cluster points into shapes such that each copy is a translate of the same template; find template as majority pattern.
# Simpler idea: maybe the "true" shape is the set of positions appearing in ALL/ most copies. Use EM-style clustering:
def recover_template(pset):
    ps=set(pset); Hg,Wg=max(i for i,_ in ps)+1,max(j for _,j in ps)+1
    clusters=[ps.copy()]
    # split: try removing one point at a time; keep split only if remainder is a translate of some current cluster or union thereof... 
    # Instead use greedy clustering by translation: start with smallest group = candidate template T. 
    # Iterative: pick cluster C; try splits where pts = S ∪ (S+d) i.e., two translates covering exactly pts.
    improved=True
    while improved:
        improved=False
        newclusters=[]
        for C in clusters:
            pts=C
            found=False
            for p in pts:
                rem={a for a in pts if a!=p}
                for q in pts:
                    if p==q: continue
                    d=(q[0]-p[0],q[1]-p[1])
                    trans={a for a in rem if (a[0]-d[0]+p[0],a[1]-d[1]+p[1]) in pts}
                    if trans == rem-{q}:
                        # valid 2-translate split
                        newclusters.append(trans); newclusters.append({p})
                        found=True; improved=True; break
                if found: break
            if not found: newclusters.append(pts)
        clusters=newclusters
    cnt=Counter(frozenset(c) for c in clusters)
    best,freq=cnt.most_common(1)[0]
    offsets=[(min(c)) for c in clusters if frozenset(c)==best]
    return best,offsets

for v in sorted(pos):
    best,offs=recover_template(pos[v])
    print('color',v,'template size',len(best),'#offsets',len(offs),'sample offs',offs[:5])

